// KZG proof validation available via BlobProofsManagerV0/V1.ValidateProofs() but NOT called during engine_getBlobsV2
// Blobs returned are taken directly from tx pool without re-validation at the EL API boundary
public bool ValidateProofs(ShardBlobNetworkWrapper wrapper)
{
    using ArrayPoolSpan<byte> cells = new(wrapper.Blobs.Length * Ckzg.BytesPerBlob * 2);
    // ... VerifyCellKzgProofBatch called with CkzgSetup
    return Ckzg.VerifyCellKzgProofBatch(flatCommitments, indices, cells,
        flatProofs, wrapper.Blobs.Length * Ckzg.CellsPerExtBlob, KzgPolynomialCommitments.CkzgSetup);
}

// PRIMARY: src/Nethermind/Nethermind.Merge.Plugin/Handlers/GetBlobsHandlerV2.cs:GetBlobsHandlerV2.HandleAsync (lines 20-72)
// engine_getBlobsV2 retrieves blobs from tx pool via TryGetBlobAndProofV1; no KZG re-verification at EL API boundary
// MaxRequest cap = 128; quick-fail if any blob missing
private const int MaxRequest = 128;
public Task<ResultWrapper<IEnumerable<BlobAndProofV2>?>> HandleAsync(byte[][] request)
{
    if (request.Length > MaxRequest) { /* TooLargeRequest error */ }
    // Returns blobs with cell proofs (V1/PeerDAS format) directly from pool
    // No ValidateProofs() called here - trust assumption: blobs validated on tx submission
    if (txPool.TryGetBlobAndProofV1(requestedBlobVersionedHash, out byte[]? blob, out byte[][]? cellProofs))
    {
        response.Add(new BlobAndProofV2(blob, cellProofs));
    }
}

// RELATED: src/Nethermind/Nethermind.Crypto/BlobProofsManagerV1.cs:BlobProofsManagerV1.ComputeProofsAndCommitments (lines 32-47)
// Cell proofs computed from blobs using CkzgLib.ComputeCellsAndKzgProofs
public void ComputeProofsAndCommitments(ShardBlobNetworkWrapper wrapper)
{
    using ArrayPoolSpan<byte> cells = new(Ckzg.BytesPerCell * Ckzg.CellsPerExtBlob);
    using ArrayPoolSpan<byte> proofs = new(Ckzg.BytesPerProof * Ckzg.CellsPerExtBlob);
    for (int i = 0; i < wrapper.Blobs.Length; i++)
    {
        Ckzg.BlobToKzgCommitment(wrapper.Commitments[i], wrapper.Blobs[i], KzgPolynomialCommitments.CkzgSetup);
        Ckzg.ComputeCellsAndKzgProofs(cells, proofs, wrapper.Blobs[i], KzgPolynomialCommitments.CkzgSetup);
    }
}
